# region: render
def render(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: digest
def digest(xs):
    return [v * v for v in xs]

# region: intake
def intake(xs, factor=3):
    return [v * factor for v in xs]

# region: shape
def shape(xs, floor_=6):
    return [v for v in xs if v >= floor_]

# region: sift
def sift(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (min(xs) - min(xs)) if xs else 0}

# region: gather
def gather(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return gather(sift(shape(intake(digest(render(raw))))))

